const results = [];

// Dicionário de estados para conversão (sigla -> extenso)
const mapEstados = {
  "ac": "Acre", "al": "Alagoas", "ap": "Amapá", "am": "Amazonas", "ba": "Bahia",
  "ce": "Ceará", "df": "Distrito Federal", "es": "Espírito Santo", "go": "Goiás",
  "ma": "Maranhão", "mt": "Mato Grosso", "ms": "Mato Grosso do Sul", "mg": "Minas Gerais",
  "pa": "Pará", "pb": "Paraíba", "pr": "Paraná", "pe": "Pernambuco", "pi": "Piauí",
  "rj": "Rio de Janeiro", "rn": "Rio Grande do Norte", "rs": "Rio Grande do Sul",
  "ro": "Rondônia", "rr": "Roraima", "sc": "Santa Catarina", "sp": "São Paulo",
  "se": "Sergipe", "to": "Tocantins"
};

for (const item of $input.all()) {
  const fieldData = item.json.field_data || [];

  // Função auxiliar para extrair e limpar os campos para lógica
  const getField = (nameKey) => {
    const field = fieldData.find(f => f.name.includes(nameKey));
    if (!field || !field.values || field.values.length === 0) return "";
    return field.values[0].toLowerCase().replace(/○__/g, '').replace(/_/g, ' ').trim();
  };

  // Função auxiliar para pegar o valor original (útil para nome, empresa, telefone)
  const getRawField = (nameKey) => {
    const field = fieldData.find(f => f.name.includes(nameKey));
    if (!field || !field.values || field.values.length === 0) return "";
    return field.values[0].replace(/○__/g, '').replace(/_/g, ' ').trim();
  };

  // Função para converter sigla em nome por extenso
  const getFullStateName = (stateStr) => {
    if (!stateStr) return "";
    const lowerState = stateStr.toLowerCase();
    return mapEstados[lowerState] || stateStr; 
  };

  // 1. Extração e Normalização
  // Mantive as chaves iguais, assumindo que os "names" no form builder não mudaram
  const normalizedData = {
    email: getRawField("email"),
    nome_completo: getRawField("full_name"),
    telefone: getRawField("phone_number"),
    cidade: getRawField("city"),
    estado: getFullStateName(getField("state")),
    empresa: getRawField("company_name"),
    tipo_empresa: getField("sua_empresa_atua_como"), 
    estado_atuacao: getField("em_qual_estado_sua_empresa_atua"),
    culturas: getField("quais_culturas"),
    produtores: getField("quantos_produtores"),
    equipe_campo: getField("equipe_para_atendimento"),
    categoria_biologicos: getField("comercializa_produtos_de_nutrição"),
    momento: getField("momento_da_sua_empresa"),
    decisor: getField("decisão_de_portfólio")
  };

  // Formata a primeira letra do estado para maiúscula caso venha do mapa
  if (mapEstados[getField("state")]) {
     normalizedData.estado = normalizedData.estado.charAt(0).toUpperCase() + normalizedData.estado.slice(1);
     if(normalizedData.estado.toLowerCase() === "mato grosso") normalizedData.estado = "Mato Grosso";
     if(normalizedData.estado.toLowerCase() === "mato grosso do sul") normalizedData.estado = "Mato Grosso do Sul";
     if(normalizedData.estado.toLowerCase() === "minas gerais") normalizedData.estado = "Minas Gerais";
     if(normalizedData.estado.toLowerCase() === "espírito santo") normalizedData.estado = "Espírito Santo";
     if(normalizedData.estado.toLowerCase() === "rio de janeiro") normalizedData.estado = "Rio de Janeiro";
     if(normalizedData.estado.toLowerCase() === "rio grande do norte") normalizedData.estado = "Rio Grande do Norte";
     if(normalizedData.estado.toLowerCase() === "rio grande do sul") normalizedData.estado = "Rio Grande do Sul";
     if(normalizedData.estado.toLowerCase() === "santa catarina") normalizedData.estado = "Santa Catarina";
     if(normalizedData.estado.toLowerCase() === "são paulo") normalizedData.estado = "São Paulo";
     if(normalizedData.estado.toLowerCase() === "distrito federal") normalizedData.estado = "Distrito Federal";
  }

  // 2. Lógica de Pontuação e Rastreio
  let score = 0;
  let desqualificado = false;
  let detalhes = [];

  // --- NOVA LÓGICA DE QUALIFICAÇÃO Q1 ---
  if (normalizedData.tipo_empresa.match(/revenda|distribuidora|distribuidor/)) {
    score += 3; detalhes.push("[Q1] +3 pts: Perfil ideal (Revenda/Distribuidora)");
  } else if (normalizedData.tipo_empresa.match(/representante|autônomo|autonomo/)) {
    desqualificado = true; detalhes.push("[Q1] DESQUALIFICADO: Representante comercial/autônomo");
  } else if (normalizedData.tipo_empresa !== "") {
    // Pega Produtor, Consultor ou qualquer outra coisa que tenha passado
    desqualificado = true; detalhes.push("[Q1] DESQUALIFICADO: Produtor, consultor ou outro perfil");
  }
  // --------------------------------------

  if (normalizedData.estado_atuacao.match(/mato grosso|goiás|paraná|mt|go|ms|pr/)) {
    score += 2; detalhes.push("[Q2] +2 pts: Estado foco de atuação");
  } else if (normalizedData.estado_atuacao.includes("outro estado")) {
    desqualificado = true; detalhes.push("[Q2] DESQUALIFICADO: Atua em outro estado");
  }

  if (normalizedData.culturas.match(/soja|milho/)) {
    score += 3; detalhes.push("[Q4] +3 pts: Culturas foco (Soja/Milho)");
  } else if (normalizedData.culturas.includes("algodão")) {
    score += 2; detalhes.push("[Q4] +2 pts: Cultura secundária (Algodão)");
  } else if (normalizedData.culturas !== "") {
    score += 1; detalhes.push("[Q4] +1 pt: Outras culturas");
  }

  if (normalizedData.produtores.includes("acima de 150")) {
    score += 3; detalhes.push("[Q5] +3 pts: Alto alcance (>150)");
  } else if (normalizedData.produtores.includes("51 a 150")) {
    score += 2; detalhes.push("[Q5] +2 pts: Alcance médio (51 a 150)");
  } else if (normalizedData.produtores !== "") {
    score += 1; detalhes.push("[Q5] +1 pt: Baixo alcance (Até 50)");
  }

  if (normalizedData.equipe_campo.includes("comercial e técnica")) {
    score += 3; detalhes.push("[Q6] +3 pts: Equipe completa");
  } else if (normalizedData.equipe_campo.includes("somente equipe")) {
    score += 2; detalhes.push("[Q6] +2 pts: Equipe parcial");
  } else if (normalizedData.equipe_campo.includes("estruturando")) {
    score += 1; detalhes.push("[Q6] +1 pt: Estruturando equipe");
  }

  if (normalizedData.categoria_biologicos.includes("já comercializamos") || normalizedData.categoria_biologicos.includes("queremos incluir")) {
    score += 3; detalhes.push("[Q7] +3 pts: Alta intenção no portfólio");
  } else if (normalizedData.categoria_biologicos.includes("conhecendo novas")) {
    score += 2; detalhes.push("[Q7] +2 pts: Conhecendo tecnologias");
  } else if (normalizedData.categoria_biologicos.includes("não temos interesse")) {
    desqualificado = true; detalhes.push("[Q7] DESQUALIFICADO: Sem interesse na categoria");
  }

  if (normalizedData.momento.includes("fechar uma parceria agora")) {
    score += 3; detalhes.push("[Q8] +3 pts: Quer fechar agora");
  } else if (normalizedData.momento.includes("avaliando fornecedores")) {
    score += 2; detalhes.push("[Q8] +2 pts: Avaliando fornecedores");
  } else if (normalizedData.momento.includes("só conhecendo")) {
    score += 1; detalhes.push("[Q8] +1 pt: Só conhecendo");
  }

  if (normalizedData.decisor.includes("sou o responsável")) {
    score += 2; detalhes.push("[Q9] +2 pts: É o decisor");
  } else if (normalizedData.decisor.includes("participo da decisão")) {
    score += 1; detalhes.push("[Q9] +1 pt: Participa da decisão");
  } else if (normalizedData.decisor !== "") {
    score += 0; detalhes.push("[Q9] 0 pts: Não é o decisor");
  }

  // 3. Classificação
  let classificacao = "Frio / Fora";

  if (desqualificado || score <= 10) {
    classificacao = "Frio / Fora";
  } else if ((score >= 11 && score <= 15) || normalizedData.momento.includes("só conhecendo")) {
    classificacao = "Morno";
  } else if (score >= 16) {
    classificacao = "Quente";
  }

  // 4. Montagem da Mensagem do WhatsApp (Evolution API)
  let emojiCode = classificacao === "Quente" ? "🔥" : classificacao === "Morno" ? "🟡" : "❄️";

  let msgWhatsapp = `🚨 *Novo Lead Processado* 🚨\n\n`;
  msgWhatsapp += `*Empresa:* ${normalizedData.empresa}\n`;
  msgWhatsapp += `*Contato:* ${normalizedData.nome_completo}\n`;
  msgWhatsapp += `*WhatsApp:* ${normalizedData.telefone}\n`;
  msgWhatsapp += `*Local:* ${normalizedData.cidade} - ${normalizedData.estado}\n\n`;

  if (desqualificado) {
    msgWhatsapp += `📊 *Classificação:* ${classificacao} ${emojiCode}\n`;
    msgWhatsapp += `*Status:* Desqualificado automaticamente\n\n`;
  } else {
    msgWhatsapp += `📊 *Classificação:* ${classificacao} ${emojiCode} (*${score} pontos*)\n\n`;
  }

  msgWhatsapp += `*📌 Resumo do Perfil:*\n`;
  msgWhatsapp += `- *Atuação:* ${normalizedData.tipo_empresa || "Não informado"}\n`;
  msgWhatsapp += `- *Culturas:* ${normalizedData.culturas || "Não informado"}\n`;
  msgWhatsapp += `- *Tamanho:* ${normalizedData.produtores || "Não informado"}\n`;
  msgWhatsapp += `- *Momento:* ${normalizedData.momento || "Não informado"}\n\n`;

  msgWhatsapp += `*📋 Detalhes da Pontuação:*\n`;
  msgWhatsapp += detalhes.join("\n");

  // 5. Montagem do Objeto Final
  results.push({
    json: {
      ...normalizedData,
      pontuacao: score,
      classificacao: classificacao,
      motivo_desqualificacao: desqualificado ? "Sim" : "Não",
      explicacao_pontuacao: detalhes.join(" \n "),
      mensagem_whatsapp: msgWhatsapp
    }
  });
}

return results;

